INSERT INTO `quest_template` (`ID`, `QuestType`, `QuestLevel`, `MinLevel`, `RewardXPDifficulty`, `Flags`, `LogTitle`, `LogDescription`, `QuestDescription`, `QuestCompletionLog`, `AreaDescription`) VALUES (55981, 2, 1, 1, 5, 0, 'Right Beneath Their Eyes / 就在他们眼皮底下', 'Have Meredy transform you into an ogre, then scout the nearby ogre citadel. / 请梅瑞迪把你变成食人魔，再去侦察附近的食人魔要塞。', 'We need to get inside Darkmaul Citadel, rescue the captain of the expedition, and stop the ogre behind all of this.$B$BMeredy is going to cast an illusion to make you look like an ogre, and you''re going to take us all in as "prisoners."$B$BI''ll be hiding my efforts to suppress the shadow magic in the meantime.$B$BSpeak with Meredy when you''re ready for her to cast the spell.$B$B我们得进入暗槌要塞，救出远征队长，阻止幕后的那个食人魔。$B$B梅瑞迪会施一个幻术让你看起来像食人魔，然后你把我们当作“俘虏”带进去。$B$B这期间我会暗中压制那股暗影魔法。$B$B准备好了就和梅瑞迪说话。', 'Report to Lady Jaina Proudmoore inside the citadel. / 到要塞里向吉安娜复命。', '');
INSERT INTO `quest_template_addon` (`ID`, `PrevQuestID`, `NextQuestID`) VALUES (55981, 56344, 55988);
INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `EmoteDelay1`, `EmoteDelay2`, `RewardText`, `VerifiedBuild`) VALUES (55981, 1, 0, 0, 0, 'We''re close to stopping all of this. We just need to push a little further.$B$B我们离阻止这一切很近了，只要再往前推进一点。', 0);
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES (55981, 0, 0, 'Have you scouted the citadel yet?$B$B你侦察过要塞了吗？', 0);
INSERT INTO `creature_queststarter` (`id`, `quest`) VALUES (156941, 55981);
INSERT INTO `creature_questender` (`id`, `quest`) VALUES (156961, 55981);
INSERT INTO `quest_template` (`ID`, `QuestType`, `QuestLevel`, `MinLevel`, `RewardXPDifficulty`, `Flags`, `LogTitle`, `LogDescription`, `QuestDescription`, `QuestCompletionLog`, `AreaDescription`) VALUES (55988, 2, 1, 1, 5, 0, 'Like Ogres to the Slaughter / 如同食人魔去屠宰', 'Slay 8 ogres within Darkmaul Citadel. / 在暗槌要塞内击杀8个食人魔。', 'This is bad, $n. Captain Kelra is bound by magic, the ogres are preparing to attack our friends, and the ritual is almost complete!$B$BWe''re behind enemy lines, so we''ll be able to get the jump on them and draw their focus away from the camp.$B$BTake down any ogres that you can.$B$B情况不妙，$n。凯尔拉队长被魔法束缚着，食人魔正准备进攻我们的朋友，仪式也快完成了！$B$B我们在敌后，可以打他们个措手不及，把他们的注意力从营地引开。$B$B能放倒多少食人魔就放倒多少。', 'Report back to Wrathion. / 向瑞斯拉克复命。', '');
INSERT INTO `quest_template_addon` (`ID`, `PrevQuestID`, `NextQuestID`) VALUES (55988, 55981, 55989);
INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `EmoteDelay1`, `EmoteDelay2`, `RewardText`, `VerifiedBuild`) VALUES (55988, 1, 0, 0, 0, 'This should buy us enough time to stop the ritual!$B$B这应该能为阻止仪式争取到足够的时间！', 0);
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES (55988, 0, 0, 'Keep fighting.$B$B继续战斗。', 0);
INSERT INTO `creature_queststarter` (`id`, `quest`) VALUES (156942, 55988);
INSERT INTO `creature_questender` (`id`, `quest`) VALUES (156942, 55988);
INSERT INTO `quest_template` (`ID`, `QuestType`, `QuestLevel`, `MinLevel`, `RewardXPDifficulty`, `Flags`, `LogTitle`, `LogDescription`, `QuestDescription`, `QuestCompletionLog`, `AreaDescription`) VALUES (55989, 2, 1, 1, 5, 0, 'Catapult Destruction / 摧毁投石机', 'Blow up 4 catapults within Darkmaul Citadel. / 炸毁暗槌要塞内的4架投石机。', 'Did you notice the catapults on our way up? It appears the ogres plan to attack our allies below.$B$BLindie anticipated something like this and provided several bombs to handle siege weapons.$B$BJust don''t shake them too hard.$B$B上来的路上你注意到那些投石机了吗？食人魔似乎打算进攻下面的盟友。$B$B琳迪早料到了，给了几颗对付攻城器械的炸弹。$B$B只是别晃得太用力。', 'Report back to Wrathion. / 向瑞斯拉克复命。', '');
INSERT INTO `quest_template_addon` (`ID`, `PrevQuestID`, `NextQuestID`) VALUES (55989, 55988, 55990);
INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `EmoteDelay1`, `EmoteDelay2`, `RewardText`, `VerifiedBuild`) VALUES (55989, 1, 0, 0, 0, 'Great work! Lindie will be glad to hear that those bombs worked perfectly.$B$B干得漂亮！琳迪听说炸弹这么好使一定很高兴。', 0);
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES (55989, 0, 0, 'The catapults must burn.$B$B投石机必须炸掉。', 0);
INSERT INTO `creature_queststarter` (`id`, `quest`) VALUES (156942, 55989);
INSERT INTO `creature_questender` (`id`, `quest`) VALUES (156942, 55989);
INSERT INTO `quest_template` (`ID`, `QuestType`, `QuestLevel`, `MinLevel`, `RewardXPDifficulty`, `Flags`, `LogTitle`, `LogDescription`, `QuestDescription`, `QuestCompletionLog`, `AreaDescription`) VALUES (55990, 2, 1, 1, 5, 0, 'Controlling their Stones / 夺取他们的石头', 'Defeat Jugnug, Wug and Grunk to recover the ward stones, then use the runes to free Captain Kelra. / 击败朱格努格、沃格和格伦克夺回结界石，再用符文石解放凯尔拉队长。', 'Captain Kelra won''t last much longer. We need to acquire the ward stones to break the ritual before it kills her.$B$BI''ll continue weakening the main ritual. Get those ward stones from the ogre lieutenants nearby.$B$B凯尔拉队长撑不了多久了。我们得拿到结界石，在仪式害死她之前打破它。$B$B我继续削弱主仪式，你去附近的食人魔副官身上取结界石。', 'Speak with Captain Kelra. / 和凯尔拉队长说话。', '');
INSERT INTO `quest_template_addon` (`ID`, `PrevQuestID`, `NextQuestID`) VALUES (55990, 55989, 55992);
INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `EmoteDelay1`, `EmoteDelay2`, `RewardText`, `VerifiedBuild`) VALUES (55990, 1, 0, 0, 0, 'Thank you for saving me, but we have no time to lose. The ogres will not stop until they have raised the dragon!$B$B谢谢你救了我，但没时间耽搁了。食人魔不把那条龙弄起来是不会罢手的！', 0);
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES (55990, 0, 0, 'So, these were the stones used to bind me?$B$B原来就是这些石头束缚了我？', 0);
INSERT INTO `creature_queststarter` (`id`, `quest`) VALUES (156961, 55990);
INSERT INTO `creature_questender` (`id`, `quest`) VALUES (156965, 55990);
