-- ALLY1F V1 (2026-11-26, Claude): Alliance 55981 -> 55988 -> 55989 -> 55990 (Darkmaul Citadel outer ring).
-- Needs the Horde DARK1A + DARK3F SQL, ALLY1B and ALLY1E. Safe to run twice. Keep worldserver stopped.
SET NAMES utf8mb4;
SET @spawn_limit := 16777215;
DELETE FROM `creature` WHERE `map` = 12175 AND `Comment` LIKE 'ALLY1F %';
DELETE FROM `gameobject` WHERE `map` = 12175 AND `Comment` LIKE 'ALLY1F %';
SELECT (SELECT COUNT(*) FROM `gameobject_template` WHERE `entry` IN (9326651, 9339865)) AS horde_objects_2,
       (SELECT COUNT(*) FROM `creature_template` WHERE `entry` IN (153239, 154103, 153580, 153581, 153582, 153583, 9100210)) AS shared_npcs_7,
       (SELECT COUNT(*) FROM `creature_template` WHERE `entry` = 156941) AS jaina_outside_1,
       (SELECT COUNT(*) FROM `creature_model_info` WHERE `DisplayID` IN (30194, 3270, 710006, 710007)) AS model_info_4;
DELETE FROM `creature_template` WHERE `entry` IN (156943, 156961, 156942, 156965);
DELETE FROM `creature_template_model` WHERE `CreatureID` IN (156943, 156961, 156942, 156965);
DELETE FROM `gameobject_template` WHERE `entry` IN (9326652, 9339866);
DELETE FROM `quest_template` WHERE `ID` IN (55981, 55988, 55989, 55990);
DELETE FROM `quest_template_addon` WHERE `ID` IN (55981, 55988, 55989, 55990);
DELETE FROM `quest_offer_reward` WHERE `ID` IN (55981, 55988, 55989, 55990);
DELETE FROM `quest_request_items` WHERE `ID` IN (55981, 55988, 55989, 55990);
DELETE FROM `creature_queststarter` WHERE `quest` IN (55981, 55988, 55989, 55990);
DELETE FROM `creature_questender` WHERE `quest` IN (55981, 55988, 55989, 55990);
DELETE FROM `quest_poi_points` WHERE `QuestID` IN (55981, 55988, 55989, 55990);
DELETE FROM `quest_poi` WHERE `QuestID` IN (55981, 55988, 55989, 55990);
SELECT COALESCE(MAX(`guid`), 0) INTO @g FROM `creature` WHERE `guid` < @spawn_limit;
SELECT COALESCE(MAX(`guid`), 0) INTO @o FROM `gameobject` WHERE `guid` < @spawn_limit;
SELECT IF(@g + 100 + 10000 < @spawn_limit AND @o + 100 + 10000 < @spawn_limit, 'guid base OK', 'ABORT: no guid room, do not continue') AS guid_check;
DROP TEMPORARY TABLE IF EXISTS tmp_ally1f;
CREATE TEMPORARY TABLE tmp_ally1f AS SELECT * FROM `gameobject_template` WHERE `entry` = 9326651;
UPDATE tmp_ally1f SET `entry` = 9326652, `Data1` = 55989;
DROP TEMPORARY TABLE tmp_ally1f;
DROP TEMPORARY TABLE IF EXISTS tmp_ally1f;
CREATE TEMPORARY TABLE tmp_ally1f AS SELECT * FROM `gameobject_template` WHERE `entry` = 9339865;
UPDATE tmp_ally1f SET `entry` = 9339866, `Data1` = 55990;
DROP TEMPORARY TABLE tmp_ally1f;
-- phases: Horde friendly NPCs and Horde click objects 1, Alliance 2, monsters shared 3
UPDATE `creature` SET `phaseMask` = 3 WHERE `map` = 12175 AND `id1` IN (153239, 154103, 153580, 153581, 153582, 153583);
UPDATE `creature` SET `phaseMask` = 1 WHERE `map` = 12175 AND `id1` IN (167596, 167633, 167598, 167632, 167631, 167183);
UPDATE `gameobject` SET `phaseMask` = 1 WHERE `map` = 12175 AND `id` IN (9326651, 9339865);
UPDATE `quest_template` SET `RequiredNpcOrGo1` = 156943, `RequiredNpcOrGoCount1` = 1, `ObjectiveText1` = 'Ask Meredy to perform the ogre transformation spell / 请梅瑞迪施展食人魔变身术' WHERE `ID` = 55981;
UPDATE `quest_template` SET `RequiredNpcOrGo2` = 154103, `RequiredNpcOrGoCount2` = 1, `ObjectiveText2` = 'Find the ogre cooking area / 找到食人魔的厨房区' WHERE `ID` = 55981;
UPDATE `quest_template` SET `RequiredNpcOrGo3` = 153580, `RequiredNpcOrGoCount3` = 1, `ObjectiveText3` = 'Greet Gor''groth (talk to him) / 向戈尔格罗斯致意（和他说话）' WHERE `ID` = 55981;
UPDATE `quest_template` SET `RequiredNpcOrGo4` = 9100210, `RequiredNpcOrGoCount4` = 1, `ObjectiveText4` = 'Reach the citadel entrance / 抵达要塞入口' WHERE `ID` = 55981;
UPDATE `quest_template` SET `RequiredNpcOrGo1` = 153239, `RequiredNpcOrGoCount1` = 8, `ObjectiveText1` = 'Ogres slain / 已击杀的食人魔' WHERE `ID` = 55988;
UPDATE `quest_template` SET `RequiredNpcOrGo1` = -9326652, `RequiredNpcOrGoCount1` = 4, `ObjectiveText1` = 'Catapults destroyed / 已炸毁的投石机' WHERE `ID` = 55989;
UPDATE `quest_template` SET `RequiredNpcOrGo1` = 153583, `RequiredNpcOrGoCount1` = 1, `ObjectiveText1` = 'Jugnug''s ward stone recovered (defeat Jugnug) / 夺回朱格努格的结界石（击败朱格努格）' WHERE `ID` = 55990;
UPDATE `quest_template` SET `RequiredNpcOrGo2` = 153582, `RequiredNpcOrGoCount2` = 1, `ObjectiveText2` = 'Wug''s ward stone recovered (defeat Wug) / 夺回沃格的结界石（击败沃格）' WHERE `ID` = 55990;
UPDATE `quest_template` SET `RequiredNpcOrGo3` = 153581, `RequiredNpcOrGoCount3` = 1, `ObjectiveText3` = 'Grunk''s ward stone recovered (defeat Grunk) / 夺回格伦克的结界石（击败格伦克）' WHERE `ID` = 55990;
UPDATE `quest_template` SET `RequiredNpcOrGo4` = -9339866, `RequiredNpcOrGoCount4` = 3, `ObjectiveText4` = 'Disable the runes holding Captain Kelra / 解除囚禁凯尔拉队长的符文' WHERE `ID` = 55990;
SELECT (SELECT COUNT(*) FROM `quest_template` WHERE `ID` IN (55981, 55988, 55989, 55990)) AS quests_4,
       (SELECT COUNT(*) FROM `creature` WHERE `Comment` LIKE 'ALLY1F %') AS npcs_4,
       (SELECT COUNT(*) FROM `gameobject` WHERE `Comment` LIKE 'ALLY1F %') AS objects_7,
       (SELECT GROUP_CONCAT(`Data1` ORDER BY `entry`) FROM `gameobject_template` WHERE `entry` IN (9326652, 9339866)) AS object_quests_55989_55990,
       (SELECT COUNT(*) FROM `creature_queststarter` WHERE `quest` IN (55981, 55988, 55989, 55990)) AS starters_4,
       (SELECT COUNT(*) FROM `creature_questender` WHERE `quest` IN (55981, 55988, 55989, 55990)) AS enders_4,
       (SELECT COUNT(*) FROM `creature` WHERE `map` = 12175 AND `id1` IN (153239, 154103, 153580, 153581, 153582, 153583) AND `phaseMask` <> 3) AS monsters_not_shared_0,
       (SELECT COUNT(*) FROM `quest_poi` WHERE `QuestID` IN (55981, 55988, 55989, 55990)) AS poi_14;
